INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('js',3,'JS OPERATORS','What is the result of this expression?','console.log(''3'' + 4);','["7","34","NaN","Error"]'::jsonb,1,'When one side is a string, + joins text instead of adding.','With a string on one side, + joins text, so ''3'' + 4 becomes ''34''.',true) ON CONFLICT (topic_id,position) DO NOTHING;
