INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('ds',0,'STACKS','Which structure follows Last-In, First-Out (LIFO)?',NULL,'["Stack","Queue","Array","Binary tree"]'::jsonb,0,'Think of a pile of plates.','A stack removes the item added most recently. A queue is First-In, First-Out.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('ds',1,'QUEUES','Which structure follows First-In, First-Out (FIFO)?',NULL,'["Queue","Stack","Heap","Hash map"]'::jsonb,0,'Like people waiting in line.','A queue serves items in the order they arrived.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('ds',2,'BIG-O','What is the time complexity of binary search on a sorted array?',NULL,'["O(log n)","O(n)","O(1)","O(n²)"]'::jsonb,0,'Each step cuts the search space in half.','Binary search halves the range every step, so it takes O(log n) time.',true) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('ds',3,'HASH MAPS','What is the average time to look up a key in a hash map?',NULL,'["O(1)","O(n)","O(log n)","O(n log n)"]'::jsonb,0,'The hash tells you exactly where to look.','A good hash function jumps straight to the right bucket: O(1) on average.',true) ON CONFLICT (topic_id,position) DO NOTHING;
