INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('dp',1,'COMPLEXITY','What is the time complexity of the plain recursive fib(n) above?',NULL,'["O(2ⁿ)","O(n)","O(log n)","O(n²)"]'::jsonb,0,'Each call makes two more calls.','The call tree roughly doubles at every level, so the plain version is exponential: O(2ⁿ).',true) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('dp',2,'MEMOIZATION','What does memoization do?',NULL,'["Caches results of calls so they are not recomputed","Converts recursion into a loop with no extra memory","Sorts the input before solving","Splits the problem into equal halves"]'::jsonb,0,'The word comes from "memo": write the answer down.','Memoization stores the result for each input, so overlapping subproblems are solved only once.',false) ON CONFLICT (topic_id,position) DO NOTHING;
INSERT INTO quiz_questions (topic_id,position,tag,prompt,code,options,correct_index,hint,explanation,options_are_code) VALUES ('dp',3,'TABULATION','Which approach builds the answer bottom-up from the smallest subproblems?',NULL,'["Tabulation","Memoization","Backtracking","Divide and conquer"]'::jsonb,0,'It fills a table, starting from the base cases.','Tabulation fills a table iteratively from the base cases up. Memoization works top-down.',false) ON CONFLICT (topic_id,position) DO NOTHING;
